function setup() {
	createCanvas(800, 800);
	// let off white background
	background(255, 252, 255);
	smooth();
	// noLoop() removed for animation
}

function draw() {
	background(255, 252, 255);

	// let the y axis
	scale(1, -1);
	translate(0, -height);

	// this centers what is drawn
	translate(width / 2, height / 2);

	noFill();
	strokeJoin(MITER);
	stroke(0, 0, 0);		
	strokeWeight(2);
	// let a small downward pointing triangle at the center of the screen
	triangle(-5, 2.5, 5, 2.5, 0, -7.5);  

	// let nine more triangles radiating from that one
	for (let i = 0; i < 10; i++) {
		triangle(-20 * i, 10 * i, 20 * i, 10 * i, 0, -20 * i); 
	}

	// let nine more triangles above that group
	strokeWeight(2);
	for (let i = 0; i < 10; i++) {
		strokeWeight(i + 0.5);
		triangle(-180 + (i * 20), 90 + (i * 10), 180 -  (i * 20), 90 + (i * 10), 0, 360 - (i * 20)); 
	}	

	// let nine more triangles to the right
	strokeWeight(2);
	for (let i = 0; i < 10; i++) {
		strokeWeight(i + 0.5);
		triangle(180, 90 - (i * 20), 360 - (i * 20), -180 + (i * 10), i * 20, -180 + (i * 10)); 
	}	

	// let nine more triangles to the left
	strokeWeight(2);
	for (let i = 0; i < 10; i++) {
		strokeWeight(i + 0.5);
		triangle(-180, 90 - (i * 20), -360 + (i * 20), -180 + (i * 10), -i * 20, -180 + (i * 10)); 
	}	
}
